#!/usr/bin/env node
/**
 * Static site build.
 *
 * The site IS the engine's output: every deck is rendered from its spec, the
 * gallery and the art atlas are generated by the same CLI an agent runs. There
 * is no second source of truth to keep in sync, which is why `vercel.json`
 * points its build command here.
 *
 *   npm run build          # engine must be compiled first
 *   node site/build.mjs    # → site/out
 */
import { execFileSync } from 'node:child_process';
import { existsSync, rmSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const out = path.join(root, 'site/out');
const cli = path.join(root, 'core-engine/dist/cli.js');

if (!existsSync(cli)) {
  console.error('engine not built: run `npm run build` first');
  process.exit(1);
}

const run = (args) => {
  console.log(`\n$ omni-carousel ${args.join(' ')}`);
  execFileSync('node', [cli, ...args], { cwd: root, stdio: 'inherit' });
};

rmSync(out, { recursive: true, force: true });

run(['examples', '--out', path.join(out, 'decks')]);
run(['gallery', '--rendered', path.join(out, 'decks'), '--out', path.join(out, 'index.html')]);
run(['canvas', '--out', path.join(out, 'atlas.html')]);
// Vercel serves 404.html for unknown paths; point it at the gallery.
execFileSync('node', ['-e', `
  const fs = require('node:fs');
  fs.copyFileSync(${JSON.stringify(path.join(out, 'index.html'))}, ${JSON.stringify(path.join(out, '404.html'))});
`]);

console.log(`\nsite built -> ${out}`);
